// Loop over input items and add a new field called 'myNewField' to the JSON of each one
// Input: Expects conversation array in $input.item.json.conversation
// Output: Adds detected_language ('en' or 'de') to the JSON item

const conversation = $input.item.json.conversation || [];
let detected_language = 'en'; // Default to English

// Simple language detection based on common German words
const german_indicators = ['Hallo', 'Danke', 'bitte', 'ja', 'nein', 'ist', 'das', 'und', 
                          'ich', 'Sie', 'für', 'mit', 'auf', 'nicht', 'eine', 'der', 'die', 'das'];
let german_count = 0;
let total_words = 0;

if (Array.isArray(conversation)) {
  conversation.forEach(turn => {
    if (turn.text) {
      const words = turn.text.split(/\s+/);
      total_words += words.length;

      words.forEach(word => {
        const cleanWord = word.toLowerCase().replace(/[.,!?;:]/g, '');
        if (german_indicators.includes(cleanWord)) {
          german_count++;
        }
      });
    }
  });
}

// If more than 5% of words are German indicators, classify as German
if (total_words > 0 && (german_count / total_words) > 0.05) { 
  detected_language = 'de';
}

console.log(`Language detection: ${detected_language} (German words: ${german_count}, Total words: ${total_words})`);

return { json: { ...$input.item.json, detected_language: detected_language } };

